#!/usr/bin/env python3
"""Fail if a publishable crate references a build-time path outside its own directory.

`cargo publish` builds the crate from a tarball containing only the crate's
own files. A compile-time path like
`include_dir!("$CARGO_MANIFEST_DIR/../../packs")` works in the workspace but
fails in the packaged build with "is not a directory" (this broke the v0.3.0
release, #367; fixed by vendoring in #368).

`cargo package` / `cargo publish --dry-run` cannot catch this in CI: they
resolve workspace path-dependencies against the crates.io index, which fails
pre-release when sibling crates aren't published yet. This check verifies the
property directly, with no network access:

  every include_str! / include_bytes! / include_dir! / include! path in a
  publishable crate must resolve inside that crate's directory.

A path starting with `$CARGO_MANIFEST_DIR` resolves from the crate root;
anything else resolves from the source file's directory (the std macro rule).
`concat!(env!("CARGO_MANIFEST_DIR"), "...")` forms are evaluated; any other
non-literal include argument fails the check (fail closed: if the path can't
be verified statically, it can't be trusted in the tarball). `concat!` forms
using `env!("OUT_DIR")` are skipped: OUT_DIR content is generated by build.rs,
which also runs for the packaged build.
Crates with `publish = false` are skipped.

Deliberately out of scope (documented here rather than checked):
- Runtime `fs` reads, including in build.rs (there is no build.rs today):
  only compile-time `include!` macros are checked.
- `path = "../..."` dependencies in Cargo.toml: cargo rewrites path
  dependencies at publish time, so they don't break the packaged build.

Run with `--self-test` to exercise the check against a fixture tree with
positive and negative cases (CI runs this before the real check), so the
check can't silently regress to always-pass.
"""

from __future__ import annotations

import re
import sys
import tempfile
from pathlib import Path

REPO = Path(__file__).resolve().parent.parent.parent

# Matches the macro name plus its opening paren; the argument is then parsed
# with balanced-paren scanning (a regex can't nest) and evaluated.
INCLUDE_RE = re.compile(r"\binclude_(?:str|bytes|dir)!\s*\(")
INCLUDE_BARE_RE = re.compile(r"(?<![_a-zA-Z])include!\s*\(")

PUBLISH_RE = re.compile(r"^\s*publish\s*=\s*false\b")

# Marker for env!("OUT_DIR") inside concat!: build-generated, safe to skip.
OUT_DIR_SENTINEL = "\0OUT_DIR\0"


def crate_is_publishable(manifest: Path) -> bool:
    for line in manifest.read_text().splitlines():
        if PUBLISH_RE.match(line):
            return False
    return True


def unescape(s: str) -> str:
    return s.encode().decode("unicode_escape")


def _parse_parens(text: str, open_idx: int) -> tuple[str, int]:
    """Return (inner text, index just past the matching close paren).

    String literals are skipped so parens inside them don't count.
    Raises ValueError on unbalanced input.
    """
    depth = 0
    in_str = False
    escape = False
    i = open_idx
    while i < len(text):
        c = text[i]
        if in_str:
            if escape:
                escape = False
            elif c == "\\":
                escape = True
            elif c == '"':
                in_str = False
        elif c == '"':
            in_str = True
        elif c == "(":
            depth += 1
        elif c == ")":
            depth -= 1
            if depth == 0:
                return text[open_idx + 1 : i], i + 1
        i += 1
    raise ValueError("unbalanced parentheses")


def _split_top_level(args: str) -> list[str]:
    """Split on commas, ignoring commas inside strings or nested parens."""
    parts: list[str] = []
    depth = 0
    in_str = False
    escape = False
    cur: list[str] = []
    for c in args:
        if in_str:
            cur.append(c)
            if escape:
                escape = False
            elif c == "\\":
                escape = True
            elif c == '"':
                in_str = False
        elif c == '"':
            in_str = True
            cur.append(c)
        elif c == "(":
            depth += 1
            cur.append(c)
        elif c == ")":
            depth -= 1
            cur.append(c)
        elif c == "," and depth == 0:
            parts.append("".join(cur))
            cur = []
        else:
            cur.append(c)
    parts.append("".join(cur))
    return parts


def _eval_include_arg(arg: str) -> str | None:
    """Evaluate an include! argument to a path string.

    Returns the path, OUT_DIR_SENTINEL if it references env!("OUT_DIR")
    (build-generated; safe to skip), or None if not statically evaluable.
    """
    arg = arg.strip()
    m = re.fullmatch(r'"((?:[^"\\]|\\.)*)"', arg, re.DOTALL)
    if m:
        return unescape(m.group(1))
    if re.fullmatch(r'env!\s*\(\s*"CARGO_MANIFEST_DIR"\s*\)', arg):
        return "$CARGO_MANIFEST_DIR"
    if re.fullmatch(r'env!\s*\(\s*"OUT_DIR"\s*\)', arg):
        return OUT_DIR_SENTINEL
    if re.match(r"concat!\s*\(", arg):
        inner, close_idx = _parse_parens(arg, arg.index("("))
        if arg[close_idx:].strip():
            return None  # trailing junk after concat!(...)
        vals = [_eval_include_arg(p) for p in _split_top_level(inner)]
        if any(v is None for v in vals):
            return None
        return "".join(vals)
    return None


def _check_one(
    crate_dir: Path, repo_root: Path, rs: Path, text: str, m: re.Match[str]
) -> str | None:
    """Return an error string for one include! match, or None if it's fine."""
    lineno = text[: m.start()].count("\n") + 1
    loc = f"{rs.relative_to(repo_root)}:{lineno}"
    try:
        inner, _ = _parse_parens(text, m.end() - 1)
    except ValueError:
        return f"{loc}: could not parse include! argument"
    val = _eval_include_arg(inner)
    if val is None:
        return f"{loc}: non-literal include path (cannot verify statically)"
    if OUT_DIR_SENTINEL in val:
        return None  # build-generated; build.rs also runs for packaged builds
    if val.startswith("$CARGO_MANIFEST_DIR"):
        resolved = (crate_dir / val[len("$CARGO_MANIFEST_DIR") :].lstrip("/")).resolve()
    else:
        resolved = (rs.parent / val).resolve()
    try:
        resolved.relative_to(crate_dir.resolve())
    except ValueError:
        return f"{loc}: path escapes the crate directory: {val}"
    return None


def check_crate(crate_dir: Path, repo_root: Path) -> list[str]:
    errors: list[str] = []
    for rs in sorted(crate_dir.rglob("*.rs")):
        text = rs.read_text()
        for m in list(INCLUDE_RE.finditer(text)) + list(
            INCLUDE_BARE_RE.finditer(text)
        ):
            err = _check_one(crate_dir, repo_root, rs, text, m)
            if err:
                errors.append(err)
    return errors


def check_repo(repo_root: Path) -> list[str]:
    errors: list[str] = []
    for manifest in sorted(repo_root.glob("crates/*/Cargo.toml")):
        if not crate_is_publishable(manifest):
            continue
        errors.extend(check_crate(manifest.parent, repo_root))
    return errors


def self_test() -> int:
    """Exercise the check against a fixture tree; fail on any mismatch."""
    # (crate name, publishable, lib.rs body, expect_error, label)
    cases = [
        (
            "good",
            True,
            'static A: &str = include_str!("data.txt");\n'
            'static B: &str = include_str!(concat!(env!("CARGO_MANIFEST_DIR"), "/data.txt"));\n',
            False,
            "in-crate literal and concat! forms pass",
        ),
        (
            "bad_literal",
            True,
            'static A: &str = include_str!("$CARGO_MANIFEST_DIR/../../outside.txt");\n',
            True,
            "escaping literal fails (the #367 bug)",
        ),
        (
            "bad_concat",
            True,
            'static A: &str = include_str!(concat!(env!("CARGO_MANIFEST_DIR"), "/../../outside.txt"));\n',
            True,
            "escaping concat! form fails (#377 nit 1)",
        ),
        (
            "bad_nonliteral",
            True,
            'const P: &str = "data.txt";\nstatic A: &str = include_str!(P);\n',
            True,
            "non-literal path fails closed",
        ),
        (
            "skipped",
            False,
            'static A: &str = include_str!("$CARGO_MANIFEST_DIR/../../outside.txt");\n',
            False,
            "publish = false crate is skipped",
        ),
        (
            "out_dir",
            True,
            'static A: &[u8] = include_bytes!(concat!(env!("OUT_DIR"), "/gen.rs"));\n',
            False,
            "OUT_DIR concat! form is skipped",
        ),
    ]
    failures = 0
    with tempfile.TemporaryDirectory() as td:
        root = Path(td)
        for name, publishable, body, _, _ in cases:
            crate_dir = root / "crates" / name
            (crate_dir / "src").mkdir(parents=True)
            pub_line = "" if publishable else "publish = false\n"
            (crate_dir / "Cargo.toml").write_text(
                f'[package]\nname = "{name}"\nversion = "0.1.0"\n{pub_line}'
            )
            (crate_dir / "src" / "lib.rs").write_text(body)
        errors = check_repo(root)
        for name, _, _, expect_error, label in cases:
            got = any(f"crates/{name}/" in e for e in errors)
            ok = got == expect_error
            if not ok:
                failures += 1
            print(f"  [{'ok' if ok else 'MISMATCH'}] {label}")
            if not ok:
                for e in errors:
                    if f"crates/{name}/" in e:
                        print(f"      error was: {e}")
    # The negative cases must name the escaping path, not just fail somehow.
    if failures:
        print(f"self-test FAILED ({failures} mismatches)")
        return 1
    print("self-test passed")
    return 0


def main() -> int:
    if "--self-test" in sys.argv:
        return self_test()
    errors = check_repo(REPO)
    if errors:
        print("crate path check FAILED:")
        for e in errors:
            print(f"  {e}")
        return 1
    print("crate path check passed")
    return 0


if __name__ == "__main__":
    sys.exit(main())
